    fq("fig-mat-5", "Matematik", "Daire Grafiği", 2, "pie", "Bir ailenin aylık 20 000 TL'lik bütçesinin harcama kalemlerine dağılımı daire grafiğinde verilmiştir.", "Aile ulaşıma ayda kaç TL harcamaktadır?", ["2500", "3000", "4000", "5000", "1500"], 1, "Ulaşım payı %15: 20 000 · 0,15 = 3000 TL."),
    fq("fig-mat-6", "Matematik", "Şekil Örüntüleri", 1, "sticks", "Kibrit çöpleriyle yan yana kareler oluşturuluyor. İlk üç adım şekilde gösterilmiştir.", "15 karelik bir dizi için kaç kibrit çöpü gerekir?", ["45", "46", "48", "60", "43"], 1, "1 kare 4, sonraki her kare 3 çöp ekler: 3n + 1 ⇒ 3 · 15 + 1 = 46."),
