    fq("fig-mat-8", "Matematik", "Üçgende Açılar", 1, "roof", "Bir evin çatı makası, şekildeki gibi tepe açısı 40° olan ikizkenar üçgen biçimindedir.", "Çatının taban açılarından birinin ölçüsü kaç derecedir?", ["50", "60", "70", "80", "140"], 2, "İkizkenar üçgende taban açıları eşittir: (180 − 40) / 2 = 70°."),
    fq("fig-mat-9", "Matematik", "Analitik Geometri", 2, "grid", "Şehir haritası bir koordinat düzlemine yerleştirilmiştir. Okul A(1, 2), kütüphane B(4, 6) noktasındadır ve 1 birim 100 metreyi göstermektedir.", "Okul ile kütüphane arasındaki kuş uçuşu uzaklık kaç metredir?", ["300", "400", "600", "500", "700"], 3, "|AB| = √((4 − 1)² + (6 − 2)²) = √(9 + 16) = 5 birim = 500 m."),
